$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$Stage='D:\Claude\swiftright\.factory-work\hosts\custom-layout-colors';$Requests=Join-Path $Stage 'requests-final-r1'
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
if(Test-Path -LiteralPath $Requests){throw 'fresh final requests required'}
New-Item -ItemType Directory -Path $Requests|Out-Null
$Rows='[{"path":"plan-prebuild-v4.json","bytes":11990,"sha256":"ecf9ba5115bcafae8db6de14d1998201f2b5b56634d9177d18cad2ffa9547337","base64":""},{"path":"build-owned-pilot-v1.ps1","bytes":11158,"sha256":"9c15fd8a6c1b43fe3f1b4a728f674e1dea0a3d5d3616c46903e9f72a07f166a2","base64":""},{"path":"plan-final-v4.json","bytes":42014,"sha256":"a1575b66bc11eef31db8463977cb3e233e8e59f574247a762be3976e40bfd884","base64":""},{"path":"build-owned-final-v1.ps1","bytes":11154,"sha256":"5c756bd02aaa9b8188bba87d786f20bd8e502d0857000237af0326c9174511f5","base64":""},{"path":"final-remote-entry.ps1","bytes":3088,"sha256":"b9056eeff6e30c2bc005c5492d250bd85f750c959563c2505fe4ff8009b8fc97","base64":""}]'|ConvertFrom-Json
foreach($Row in @($Rows)){
  $P=Join-Path $Requests $Row.path
